insert into public.exam_questionnaires (course_id, questions, passing_score, submission_deadline) values
  ((select id from public.courses where title = $s$Numerical Weather Prediction & Model Guidance$s$ limit 1), $s$[{"id":"nwp-q1","question":"Which NWP model family is operationally used by IMD for regional forecasting?","options":["NCUM & GFS","ERA5 only","WRF-Lambert","CFSv2 only"],"correct":0},{"id":"nwp-q2","question":"What does MOS stand for in statistical post-processing?","options":["Model Output Statistics","Monsoon Onset System","Mean Observation Series","Multi-level Observation System"],"correct":0},{"id":"nwp-q3","question":"Bias correction for a station forecast primarily removes:","options":["Systematic model error","Random sensor error","Data assimilation noise","Human analysis error"],"correct":0},{"id":"nwp-q4","question":"An ensemble forecast spread that is too narrow indicates:","options":["Overconfidence in the solution","High forecast skill","Large observation gaps","Improper model resolution"],"correct":0},{"id":"nwp-q5","question":"Which product is essential for probabilistic rainfall forecasts?","options":["Ensemble probability charts","Single deterministic run","Raw MSLP chart","Satellite cloud imagery"],"correct":0}]$s$::jsonb, 60, $s$2026-10-31T23:59:59+05:30$s$),
  ((select id from public.courses where title = $s$Satellite Remote Sensing for Weather Forecasting$s$ limit 1), $s$[{"id":"sat-q1","question":"INSAT-3DR carries which radiometer essential for atmospheric profiling?","options":["Sounder","SAR","Scatterometer","Ozone mapper"],"correct":2},{"id":"sat-q2","question":"Rapidly growing cumulonimbus cells appear coldest (most intense) in which channel?","options":["Infrared window 10.5 um","Visible 0.65 um","Microwave 89 GHz","Shortwave IR 3.9 um"],"correct":0},{"id":"sat-q3","question":"The IMSRA product estimates which parameter over India?","options":["Rainfall intensity","Cloud top temperature","Sea surface temperature","Wind speed"],"correct":0},{"id":"sat-q4","question":"A water vapor channel (6.2 um) is most useful for detecting:","options":["Mid-tropospheric moisture","Ocean surface winds","Cloud base height","Surface temperature"],"correct":0},{"id":"sat-q5","question":"Nowcasting uses satellite imagery primarily for:","options":["Continuous monitoring of thunderstorm development","Climatological averages","Model initialization only","Long-range monsoon prediction"],"correct":0}]$s$::jsonb, 60, $s$2026-11-15T23:59:59+05:30$s$),
  ((select id from public.courses where title = $s$Radar Meteorology & Doppler Data Interpretation$s$ limit 1), $s$[{"id":"rad-q1","question":"A mesocyclone is identified in Doppler velocity data as:","options":["Opposing radial velocities adjacent to each other","Uniform flow","No echo region","Turbulent clear-air echo"],"correct":0},{"id":"rad-q2","question":"The bright band in reflectivity is caused by:","options":["Melting snowflakes","Strong updrafts","Hail stones","Clear air turbulence"],"correct":0},{"id":"rad-q3","question":"VIL (Vertically Integrated Liquid) is a proxy for:","options":["Storm severity","Cloud height","Surface wind","Dew point depression"],"correct":0},{"id":"rad-q4","question":"A hook echo signature is classically associated with:","options":["Supercell tornadogenesis","Downburst","Dust storm","Squall line"],"correct":0},{"id":"rad-q5","question":"Which radar product best tracks cell movement for nowcasting?","options":["Cell tracking & extrapolation","Base reflectivity only","VAD wind profile only","Single snapshot"],"correct":0}]$s$::jsonb, 60, $s$2026-11-30T23:59:59+05:30$s$),
  ((select id from public.courses where title = $s$Cyclone Tracking & Warning Systems$s$ limit 1), $s$[{"id":"cyc-q1","question":"The Genesis Potential Index (GPI) combines:","options":["Vorticity, humidity, vertical wind shear, SST","Pressure, temperature, humidity","Wind speed and direction","Cloud cover and rain rate"],"correct":0},{"id":"cyc-q2","question":"Rapid intensification is typically defined as wind increase of:","options":["55+ knots in 24 hours","5 knots in a week","10 knots in a month","20 knots in a day"],"correct":0},{"id":"cyc-q3","question":"The Dvorak T-number is estimated from:","options":["Satellite cloud patterns","Buoy measurements","Aircraft only","Radar velocity"],"correct":2},{"id":"cyc-q4","question":"Storm surge is primarily driven by:","options":["Surface wind stress and atmospheric pressure deficit","Ocean temperature","Sea wave period","Tidal currents only"],"correct":0},{"id":"cyc-q5","question":"CWC bulletins must be issued at minimum intervals of:","options":["3 hourly during alert period","24 hourly","Weekly","Once at landfall"],"correct":0}]$s$::jsonb, 60, $s$2026-12-15T23:59:59+05:30$s$),
  ((select id from public.courses where title = $s$Agro-Meteorology & Crop-Weather Advisory$s$ limit 1), $s$[{"id":"agro-q1","question":"Agromet advisories are primarily disseminated through:","options":["Grameen Mausam Seva (Kisan SMS)","Only print media","Aviation NOTAM","Marine forecasts only"],"correct":0},{"id":"agro-q2","question":"Crop weather calendars are aligned with:","options":["Crop growth phenophases","Financial quarters","Exam schedules","Public holidays"],"correct":0},{"id":"agro-q3","question":"Which index is used to assess crop moisture stress?","options":["Soil moisture deficit index","Heat index of buildings","Wet bulb globe only","Wind chill"],"correct":0},{"id":"agro-q4","question":"Sowing advisories depend most heavily on:","options":["Spatial rainfall forecast","Ocean wave height","Airport visibility","Sunspot activity"],"correct":0}]$s$::jsonb, 60, $s$2026-11-05T23:59:59+05:30$s$),
  ((select id from public.courses where title = $s$Hydrology & Rain Gauge Calibration$s$ limit 1), $s$[{"id":"hyd-q1","question":"A tipping bucket rain gauge records precipitation in increments of:","options":["0.5 mm typically","5 cm","50 mm","10 cm"],"correct":0},{"id":"hyd-q2","question":"Areal rainfall is best estimated from point gauges using:","options":["Thiessen polygons","Simple averaging of two stations","Satellite alone","No method needed"],"correct":0},{"id":"hyd-q3","question":"Telemetric gauge data validation flags:","options":["Sudden sensor jumps or stuck tips","Model output","CPC analysis","Climate normals"],"correct":0},{"id":"hyd-q4","question":"For flood meteorology, the most relevant forecast product is:","options":["Quantitative precipitation forecast (QPF)","Sea surface temperature chart","Atmospheric composition","UV index"],"correct":0}]$s$::jsonb, 60, $s$2026-11-20T23:59:59+05:30$s$),
  ((select id from public.courses where title = $s$Climate Modeling & Monsoon Dynamics$s$ limit 1), $s$[{"id":"clim-q1","question":"The Indian summer monsoon onset is declared based on:","options":["Objective criteria combining rainfall and dynamics","A single station reading","Calendar date only","Sea level only"],"correct":0},{"id":"clim-q2","question":"Active and break spells in monsoon are linked to:","options":["Monsoon trough oscillation","El Nino alone","Ozone depletion","Solar flares"],"correct":0},{"id":"clim-q3","question":"Long-range forecasts (LRF) for monsoon are issued:","options":["Seasonally ahead","Hourly","Every minute","After the season ends"],"correct":0},{"id":"clim-q4","question":"Coupled climate models are used to forecast:","options":["Seasonal-scale climate variations","Thunderstorms only","Fog events only","Lightning signatures only"],"correct":0}]$s$::jsonb, 60, $s$2026-12-01T23:59:59+05:30$s$)
